import { useEffect, useRef, useState, useMemo, useCallback } from "react";
import * as THREE from "three";

/* ================= embedded 3D geometry (from user's Blender model) ================= */
const PARTS_DATA = [{"name":"body","translation":[-0.03867,0.04579,0.09573],"rotation":[0,0,0,1],"scale":[1.2,0.81015,0.81015],"positions":"","indices":"","areaPct":78.44},{"name":"eyes1","translation":[0.9664,0.23983,-0.27511],"rotation":[0,0,0,1],"scale":[0.06992,0.06992,0.06992],"positions":"","indices":"","areaPct":0.45},{"name":"eyes2","translation":[0.8953,0.2355,0.56629],"rotation":[0,0,0,1],"scale":[0.06992,0.06992,0.06992],"positions":"","indices":"","areaPct":0.45},{"name":"jinurami-high1","translation":[-0.15524,0.91505,0.04797],"rotation":[-0.06247,-0.74757,-0.66032,0.03485],"scale":[0.29325,0.1,0.23758],"positions":"","indices":"","areaPct":3.35},{"name":"jinurami-high2","translation":[-0.69289,0.7161,0.10442],"rotation":[-0.06101,-0.72908,-0.68014,0.04618],"scale":[0.23113,0.07882,0.18725],"positions":"","indices":"","areaPct":2.08},{"name":"jinurami-side2","translation":[-0.1001,0.00018,-0.70834],"rotation":[0,0,0,1],"scale":[0.29325,0.1,0.23758],"positions":"","indices":"","areaPct":3.35},{"name":"jinurami-under","translation":[-0.46998,-0.71266,0.07323],"rotation":[-0.06247,-0.74757,-0.66032,0.03485],"scale":[0.29325,0.1,0.23758],"positions":"","indices":"","areaPct":3.35},{"name":"jinurani-side1","translation":[-0.0268,-0.14098,0.89768],"rotation":[0,0,0,1],"scale":[0.29325,0.1,0.23758],"positions":"","indices":"","areaPct":3.35},{"name":"tail","translation":[-1.33714,-0.06486,0.00524],"rotation":[0.04986,0.13827,-0.71377,0.68479],"scale":[0.26286,0.26286,0.26286],"positions":"","indices":"","areaPct":5.16}];

const EYE_NAMES = ["eyes1", "eyes2"];
const PAINTABLE_NAMES = PARTS_DATA.map((p) => p.name).filter((n) => !EYE_NAMES.includes(n));

function b64ToFloat32(b64) {
  const bin = atob(b64);
  const buf = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) buf[i] = bin.charCodeAt(i);
  return new Float32Array(buf.buffer);
}
function b64ToUint16(b64) {
  const bin = atob(b64);
  const buf = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) buf[i] = bin.charCodeAt(i);
  return new Uint16Array(buf.buffer);
}

// Build each part's BufferGeometry once (shared across every fish instance).
const GEOMETRIES = {};
PARTS_DATA.forEach((p) => {
  const geo = new THREE.BufferGeometry();
  geo.setAttribute("position", new THREE.BufferAttribute(b64ToFloat32(p.positions), 3));
  geo.setIndex(new THREE.BufferAttribute(b64ToUint16(p.indices), 1));
  geo.computeVertexNormals();
  GEOMETRIES[p.name] = geo;
});

/* ================= color helpers ================= */
function hexToHsl(hex) {
  let r = parseInt(hex.slice(1, 3), 16) / 255;
  let g = parseInt(hex.slice(3, 5), 16) / 255;
  let b = parseInt(hex.slice(5, 7), 16) / 255;
  const max = Math.max(r, g, b), min = Math.min(r, g, b);
  let h, s, l = (max + min) / 2;
  if (max === min) { h = s = 0; }
  else {
    const d = max - min;
    s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
    switch (max) {
      case r: h = (g - b) / d + (g < b ? 6 : 0); break;
      case g: h = (b - r) / d + 2; break;
      default: h = (r - g) / d + 4;
    }
    h *= 60;
  }
  return [h, s * 100, l * 100];
}
function classify(hex) {
  const [h, s, l] = hexToHsl(hex);
  if (l < 22) return "black";
  if (h >= 8 && h <= 48 && s > 35) return "orange";
  return "other";
}

const PALETTE = [
  { hex: "#FF8A5B", name: "주황" },
  { hex: "#E8672B", name: "진한 주황" },
  { hex: "#FFC98B", name: "연한 주황" },
  { hex: "#14151A", name: "검정" },
  { hex: "#54525E", name: "짙은 회색" },
  { hex: "#9AA6E8", name: "라벤더" },
  { hex: "#8FD4C1", name: "민트" },
  { hex: "#F3EDE3", name: "펄 화이트" },
];
const ORANGE_SHADES = ["#FF8A5B", "#E8672B", "#FFC98B"];
const BLACK_SHADES = ["#14151A", "#26262E"];
const OTHER_SHADES = ["#9AA6E8", "#8FD4C1", "#F3EDE3"];
const DEFAULT_COLOR = "#F3EDE3";
const EYE_COLOR = "#20212B";

function pick(arr) { return arr[Math.floor(Math.random() * arr.length)]; }

function defaultColors() {
  const c = {};
  PAINTABLE_NAMES.forEach((n) => (c[n] = DEFAULT_COLOR));
  return c;
}

function generateRivalColors() {
  const bias = Math.random();
  const c = {};
  PAINTABLE_NAMES.forEach((n) => {
    const roll = Math.random();
    if (bias < 0.45) c[n] = roll < 0.7 ? pick(ORANGE_SHADES) : pick(OTHER_SHADES);
    else if (bias < 0.85) c[n] = roll < 0.7 ? pick(BLACK_SHADES) : pick(OTHER_SHADES);
    else c[n] = pick([...ORANGE_SHADES, ...BLACK_SHADES, ...OTHER_SHADES]);
  });
  return c;
}

// area weights come straight from the actual 3D model's surface area (computed from the .glb geometry),
// not a designer-picked number.
const AREA_PCT = {};
PARTS_DATA.forEach((p) => { AREA_PCT[p.name] = p.areaPct; });

function computeStats(colors) {
  let orange = 0, black = 0, wSum = 0;
  PAINTABLE_NAMES.forEach((n) => {
    const w = AREA_PCT[n];
    const cat = classify(colors[n]);
    if (cat === "orange") orange += w;
    if (cat === "black") black += w;
    wSum += w;
  });
  return {
    orangePct: Math.round((orange / wSum) * 100),
    blackPct: Math.round((black / wSum) * 100),
  };
}

/* ================= boldness presets (categorical, not a slider) ================= */
const BOLDNESS_PRESETS = [
  { id: "shy", label: "소극적", emoji: "🫥", value: 20 },
  { id: "normal", label: "보통", emoji: "😐", value: 50 },
  { id: "bold", label: "대담함", emoji: "🦁", value: 80 },
];
function boldnessValue(id) { return BOLDNESS_PRESETS.find((b) => b.id === id)?.value ?? 50; }

/* ================= scoring — internal numbers are never shown to the user ================= */
// Diet effect is only modeled for orange/black, the two diets with a verified 7-day reversal
// result in Kato & Karino (2024). No arbitrary per-day multipliers — the condition is fixed at
// 7 days, the only duration actually tested in the paper.
function colorScore(stats, diet) {
  const { orangePct, blackPct } = stats;
  if (diet === "orange") return orangePct - blackPct * 0.3;
  return blackPct - orangePct * 0.3; // diet === "black"
}
// Godin & Dugatkin (1996): with a predator threat, boldness gates preference regardless of color;
// without one, color gates preference regardless of boldness. The two cues never blend.
function matchScore(stats, boldnessId, diet, predatorPresent) {
  if (predatorPresent) return boldnessValue(boldnessId);
  return colorScore(stats, diet);
}
function verdict(scoreA, scoreB) {
  const diff = Math.abs(scoreA - scoreB);
  const leader = scoreA >= scoreB ? "A" : "B";
  let strength;
  if (diff < 6) strength = "거의 차이 없음";
  else if (diff < 22) strength = "약하게 선호";
  else strength = "뚜렷하게 선호";
  return { leader, strength, diff };
}

/* ================= three.js fish renderer (no external loader — geometry is embedded) ================= */
function FishCanvas({ colors, editable, onPartClick, height = 260, initialRotY = 0.4, dim = false }) {
  const containerRef = useRef(null);
  const stateRef = useRef({});
  const onPartClickRef = useRef(onPartClick);
  onPartClickRef.current = onPartClick;

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const scene = new THREE.Scene();
    scene.background = null;

    const camera = new THREE.PerspectiveCamera(40, 1, 0.1, 100);
    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    container.appendChild(renderer.domElement);

    const group = new THREE.Group();
    scene.add(group);

    const meshes = {};
    PARTS_DATA.forEach((p) => {
      const isEye = EYE_NAMES.includes(p.name);
      const mat = new THREE.MeshStandardMaterial({
        color: isEye ? EYE_COLOR : DEFAULT_COLOR,
        roughness: isEye ? 0.15 : 0.28,
        metalness: 0.06,
      });
      const mesh = new THREE.Mesh(GEOMETRIES[p.name], mat);
      mesh.position.set(...p.translation);
      mesh.quaternion.set(p.rotation[0], p.rotation[1], p.rotation[2], p.rotation[3]);
      mesh.scale.set(...p.scale);
      mesh.userData.name = p.name;
      group.add(mesh);
      meshes[p.name] = mesh;
    });

    // frame the camera to the model's actual bounding sphere
    const box = new THREE.Box3().setFromObject(group);
    const sphere = box.getBoundingSphere(new THREE.Sphere());
    const dist = sphere.radius / Math.sin((camera.fov * Math.PI) / 360) * 1.35;
    camera.position.set(sphere.center.x, sphere.center.y + sphere.radius * 0.15, sphere.center.z + dist);
    camera.lookAt(sphere.center);

    const hemi = new THREE.HemisphereLight(0xfff2e6, 0x4a4560, 0.9);
    scene.add(hemi);
    const key = new THREE.DirectionalLight(0xffffff, 1.1);
    key.position.set(3, 4, 5);
    scene.add(key);
    const fill = new THREE.DirectionalLight(0x9ac8ff, 0.35);
    fill.position.set(-4, -1, -3);
    scene.add(fill);

    let raf;
    let dragging = false, moved = false, lastX = 0, lastY = 0;
    let rotY = initialRotY, rotX = -0.05;
    const raycaster = new THREE.Raycaster();
    const pointer = new THREE.Vector2();

    function applyRot() {
      group.rotation.y = rotY;
      group.rotation.x = rotX;
    }
    applyRot();

    function animate() {
      if (!dragging) rotY += 0.0028;
      applyRot();
      renderer.render(scene, camera);
      raf = requestAnimationFrame(animate);
    }
    animate();

    function onDown(e) {
      dragging = true; moved = false;
      lastX = e.clientX; lastY = e.clientY;
    }
    function onMove(e) {
      if (!dragging) return;
      const dx = e.clientX - lastX, dy = e.clientY - lastY;
      if (Math.abs(dx) + Math.abs(dy) > 6) moved = true;
      rotY += dx * 0.008;
      rotX = Math.max(-0.6, Math.min(0.6, rotX + dy * 0.006));
      lastX = e.clientX; lastY = e.clientY;
    }
    function onUp(e) {
      const wasDragging = dragging;
      dragging = false;
      if (moved || !editable || !wasDragging) return;
      const rect = renderer.domElement.getBoundingClientRect();
      pointer.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
      pointer.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
      raycaster.setFromCamera(pointer, camera);
      const hits = raycaster.intersectObjects(
        Object.entries(meshes).filter(([n]) => !EYE_NAMES.includes(n)).map(([, m]) => m)
      );
      if (hits.length && onPartClickRef.current) onPartClickRef.current(hits[0].object.userData.name);
    }

    const dom = renderer.domElement;
    dom.style.touchAction = "none";
    dom.addEventListener("pointerdown", onDown);
    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp);

    function resize() {
      const w = container.clientWidth, h = height;
      renderer.setSize(w, h);
      camera.aspect = w / h;
      camera.updateProjectionMatrix();
    }
    resize();
    const ro = new ResizeObserver(resize);
    ro.observe(container);

    stateRef.current = { meshes };

    return () => {
      cancelAnimationFrame(raf);
      ro.disconnect();
      dom.removeEventListener("pointerdown", onDown);
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp);
      renderer.dispose();
      if (container.contains(dom)) container.removeChild(dom);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [editable]);

  // update colors whenever the colors prop changes, without rebuilding the scene
  useEffect(() => {
    const meshes = stateRef.current.meshes;
    if (!meshes) return;
    PAINTABLE_NAMES.forEach((n) => {
      const hex = colors[n] || DEFAULT_COLOR;
      meshes[n]?.material.color.set(hex);
    });
  }, [colors]);

  return (
    <div
      ref={containerRef}
      style={{
        width: "100%", height,
        cursor: editable ? "pointer" : dim ? "default" : "grab",
        filter: dim ? "blur(2.5px) grayscale(0.2)" : "none",
        opacity: dim ? 0.55 : 1,
        pointerEvents: dim ? "none" : "auto",
      }}
    />
  );
}

/* ================= crown (user's own image asset, transparent PNG, embedded) ================= */
const CROWN_B64 = "";
function Crown({ style }) {
  return <img src={`data:image/png;base64,${CROWN_B64}`} alt="" style={{ width: 72, ...style }} />;
}


/* ================= background image (from the user's own reference asset, resized) ================= */
const DESIGN_BG_B64 = "";

/* ================= female observer (blurred, facing away — the male is what's in focus) ================= */
function FemaleObserver() {
  const [colors] = useState(() => {
    const c = {};
    PAINTABLE_NAMES.forEach((n) => (c[n] = "#B9AFD9"));
    return c;
  });
  return (
    <div style={{ position: "absolute", bottom: 6, right: 10, width: 92, height: 92, zIndex: 1 }}>
      <FishCanvas colors={colors} editable={false} height={92} initialRotY={Math.PI + 0.3} dim />
    </div>
  );
}


export default function GuppyMateChoiceLab3D() {
  const [diet, setDiet] = useState("orange");
  const [predatorPresent, setPredatorPresent] = useState(false);
  const [boldnessAId, setBoldnessAId] = useState("normal");
  const [colors, setColors] = useState(defaultColors);
  const [brush, setBrush] = useState(PALETTE[0].hex);
  const [rival, setRival] = useState(() => ({
    colors: generateRivalColors(),
    boldnessId: pick(BOLDNESS_PRESETS).id,
  }));
  const [view, setView] = useState("design");
  const [explanation, setExplanation] = useState(null);
  const [loadingExplain, setLoadingExplain] = useState(false);

  const statsA = useMemo(() => computeStats(colors), [colors]);
  const statsB = useMemo(() => computeStats(rival.colors), [rival]);

  const scoreA = matchScore(statsA, boldnessAId, diet, predatorPresent);
  const scoreB = matchScore(statsB, rival.boldnessId, diet, predatorPresent);
  const { leader, strength } = verdict(scoreA, scoreB);
  // bar width is derived from the SIGNED difference around a 50/50 midpoint, not a ratio of the
  // raw scores — a ratio breaks (and can even point the wrong way) whenever a score is negative,
  // which colorScore/boldness values often are. This guarantees the bar always agrees with `leader`.
  const diffSigned = scoreA - scoreB;
  const barA = Math.max(8, Math.min(92, Math.round(50 + diffSigned * 1.4)));

  function paint(partName) {
    setColors((c) => ({ ...c, [partName]: brush }));
  }
  function reroll() {
    setRival({ colors: generateRivalColors(), boldnessId: pick(BOLDNESS_PRESETS).id });
    setExplanation(null);
  }
  function submit() { setView("result"); setExplanation(null); }

  const askAi = useCallback(async () => {
    setLoadingExplain(true);
    setExplanation(null);
    const boldA = BOLDNESS_PRESETS.find((b) => b.id === boldnessAId).label;
    const boldB = BOLDNESS_PRESETS.find((b) => b.id === rival.boldnessId).label;
    const prompt = `너는 구피(Poecilia reticulata) 짝 선택 행동생태학 연구를 바탕으로 시뮬레이션 결과를 해설하는 역할이야.
계산은 이미 프로그램이 끝냈고, 너는 그 결과가 왜 나왔는지만 설명해. 새로운 과학적 근거나 수치를 지어내지 마.

조건:
포식자 존재 여부: ${predatorPresent ? "있음" : "없음"}
${predatorPresent ? "" : `암컷의 먹이 경험: ${diet === "orange" ? "주황색 먹이" : "검은색 먹이"} (7일, Kato & Karino 2024에서 실제로 검증된 조건)`}

수컷 A (사용자 디자인): 주황 비중 ${statsA.orangePct}%, 검정 비중 ${statsA.blackPct}%, 행동 성향 ${boldA}
수컷 B (비교군): 주황 비중 ${statsB.orangePct}%, 검정 비중 ${statsB.blackPct}%, 행동 성향 ${boldB}

프로그램의 판정: 수컷 ${leader} ${strength}

이 판정 로직의 근거:
- 포식자가 없을 때는 Rodd et al.(2002)의 먹이색 감각 편향 가설과 Kato & Karino(2024)의 결과만 근거로 색을 기준 삼음.
- 포식자가 있을 때는 Godin & Dugatkin(1996)의 결과를 근거로, 색과 무관하게 더 대담한 개체를 선호한다고 가정함.

지금 조건에 실제로 적용된 근거만 골라서 왜 이 판정이 나왔는지 3문장 이내로 한국어로 설명해줘. 확률이나 퍼센트를 새로 만들어내지 말고, 이건 실제 구피 데이터가 아니라 문헌에 기반한 시뮬레이션이라는 점을 한 문장으로 짚어줘.`;
    try {
      const response = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          model: "claude-sonnet-4-6",
          max_tokens: 700,
          messages: [{ role: "user", content: prompt }],
        }),
      });
      const data = await response.json();
      const text = (data.content || []).map((b) => (b.type === "text" ? b.text : "")).filter(Boolean).join("\n");
      setExplanation(text || "설명을 생성하지 못했어.");
    } catch (e) {
      setExplanation("AI 설명을 불러오는 데 실패했어. 잠시 후 다시 시도해줘.");
    }
    setLoadingExplain(false);
  }, [diet, predatorPresent, boldnessAId, rival, statsA, statsB, leader, strength]);

  return (
    <div style={styles.page}>
      <style>{`
        @font-face {
          font-family: 'ChosunGu';
          src: url(data:font/woff2;base64,) format('woff2');
          font-weight: 400 700;
          font-display: swap;
        }
        * { box-sizing: border-box; }
        .gm-btn { cursor: pointer; transition: transform .12s ease, background .12s ease; }
        .gm-btn:active { transform: scale(0.96); }
        .gm-fade { animation: gmFade .45s ease both; }
        @keyframes gmFade { from { opacity:0; transform: translateY(6px);} to { opacity:1; transform:none; } }
        .gm-bar-fill { transition: width .7s cubic-bezier(.2,.8,.2,1); }
      `}</style>

      <header style={styles.header}>
        <div style={styles.eyebrow}>HER CHOICE</div>
        <h1 style={styles.h1}>What makes a male guppy attractive?</h1>
        <p style={styles.headerNote}>
          색깔의 면적은 3D 모델의 표면적 비율로 계산되며, 숫자로 된 확률은 명확성을 위해 표시되지 않습니다.
        </p>
        <p style={styles.refNote}>참고자료 — Rodd et al.(2002), Kato &amp; Karino(2024), Godin &amp; Dugatkin(1996)</p>
      </header>

      {view === "design" && (
        <div style={styles.grid} className="gm-fade">
          <section style={styles.panel}>
            <div style={styles.panelLabel}>환경</div>

            <div style={styles.smallLabel}>포식자 위협</div>
            <div style={styles.rowWrap}>
              <button className="gm-btn" onClick={() => setPredatorPresent(false)}
                style={{ ...styles.chip, ...(!predatorPresent ? styles.chipActive : {}) }}>없음</button>
              <button className="gm-btn" onClick={() => setPredatorPresent(true)}
                style={{ ...styles.chip, ...(predatorPresent ? styles.chipActive : {}) }}>있음</button>
            </div>

            {predatorPresent ? (
              <>
                <p style={styles.smallNote}>
                  포식자의 위협이 가해질 시 포식자가 있으면 Godin &amp; Dugatkin(1996)에 의해 색은 무시되고
                  행동 성향만 반영하여 비교됩니다.
                </p>
                <div style={{ ...styles.smallLabel, marginTop: 14 }}>수컷 A의 행동 성향</div>
                <div style={styles.rowWrap}>
                  {BOLDNESS_PRESETS.map((b) => (
                    <button key={b.id} className="gm-btn" onClick={() => setBoldnessAId(b.id)}
                      style={{ ...styles.chip, ...(boldnessAId === b.id ? styles.chipActive : {}) }}>
                      {b.label}
                    </button>
                  ))}
                </div>
                <div style={styles.badge}>*실측값이 아니며 · 시뮬레이션 입력값을 기반으로 합니다</div>
              </>
            ) : (
              <>
                <div style={{ ...styles.smallLabel, marginTop: 14 }}>먹이 경험 (7일 고정)</div>
                <div style={styles.rowWrap}>
                  <button className="gm-btn" onClick={() => setDiet("orange")}
                    style={{ ...styles.chip, ...(diet === "orange" ? styles.chipActive : {}) }}>주황 먹이</button>
                  <button className="gm-btn" onClick={() => setDiet("black")}
                    style={{ ...styles.chip, ...(diet === "black" ? styles.chipActive : {}) }}>검은 먹이</button>
                </div>
                <div style={styles.badgeVerified}>Kato &amp; Karino(2024) 검증 조건 (7일)</div>
              </>
            )}
          </section>

          <section style={{ ...styles.panelWide, ...styles.designPanelBg, position: "relative", overflow: "hidden" }}>
            <div style={styles.designPanelInner}>
              <div style={styles.panelLabel}>수컷 디자인 — 3D 모델을 드래그로 돌리고, 부위를 클릭해서 색칠</div>
              <FishCanvas colors={colors} editable onPartClick={paint} />
              <div style={styles.rowWrap}>
                {PALETTE.map((c) => (
                  <button key={c.hex} className="gm-btn" onClick={() => setBrush(c.hex)} title={c.name}
                    style={{ width: 30, height: 30, borderRadius: "50%", background: c.hex,
                      border: brush === c.hex ? "3px solid #2B2B33" : "2px solid rgba(43,43,51,0.15)" }} />
                ))}
              </div>
              <button className="gm-btn" style={styles.primaryBtn} onClick={submit}>내 물고기를 뽐내보자</button>
            </div>
            <FemaleObserver />
          </section>

          <section style={styles.panel}>
            <div style={styles.panelLabel}>측정값</div>
            <Readout label="주황 비중" value={`${statsA.orangePct}%`} />
            <Readout label="검정 비중" value={`${statsA.blackPct}%`} />
            <p style={styles.smallNote}>
              부위별 비중은 이 3D 모델의 실제 표면적(지오메트리에서 계산됨)을 기준으로 해요.
            </p>
          </section>
        </div>
      )}

      {view === "result" && (
        <div className="gm-fade">
          <div style={styles.resultGrid}>
            <FishResultCard title="수컷 A · 당신의 디자인" colors={colors} stats={statsA}
              boldnessId={boldnessAId} predatorPresent={predatorPresent} isLeader={leader === "A"} />
            <FishResultCard title="수컷 B · 비교군" colors={rival.colors} stats={statsB}
              boldnessId={rival.boldnessId} predatorPresent={predatorPresent} isLeader={leader === "B"} />
          </div>

          <div style={styles.verdictWrap}>
            <div style={styles.verdictText}>수컷 {leader} {strength}</div>
            <div style={styles.probBar}>
              <div className="gm-bar-fill" style={{ width: `${barA}%`, background: "#4FA8D8", height: "100%" }} />
              <div className="gm-bar-fill" style={{ width: `${100 - barA}%`, background: "#9AA6E8", height: "100%" }} />
            </div>
            <div style={styles.probLabels}><span>A</span><span>B</span></div>
          </div>

          <div style={styles.actionRow}>
            <button className="gm-btn" style={styles.secondaryBtn} onClick={() => setView("design")}>← 다시 디자인하기</button>
            <button className="gm-btn" style={styles.secondaryBtn} onClick={reroll}>비교군 다시 생성</button>
            <button className="gm-btn" style={styles.primaryBtn} onClick={askAi} disabled={loadingExplain}>
              {loadingExplain ? "AI가 근거를 분석하는 중…" : "AI에게 이유 물어보기"}
            </button>
          </div>

          {explanation && (
            <div style={styles.explainBox} className="gm-fade">
              <div style={styles.panelLabel}>AI의 설명</div>
              <p style={{ margin: 0, lineHeight: 1.7, color: "#3A3742" }}>{explanation}</p>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

function Readout({ label, value }) {
  return (
    <div style={styles.readoutRow}>
      <span style={styles.readoutLabel}>{label}</span>
      <span style={styles.readoutValue}>{value}</span>
    </div>
  );
}

function FishResultCard({ title, colors, stats, boldnessId, predatorPresent, isLeader }) {
  const bold = BOLDNESS_PRESETS.find((b) => b.id === boldnessId);
  return (
    <div style={{ ...styles.panelWide, position: "relative", border: isLeader ? "2px solid #4FA8D8" : "1px solid rgba(43,43,51,0.08)" }}>
      {isLeader && <Crown style={{ position: "absolute", top: 34, left: "50%", width: 54, transform: "translateX(-50%) rotate(-4deg)", zIndex: 2, filter: "drop-shadow(0 3px 4px rgba(0,0,0,0.18))" }} />}
      <div style={styles.panelLabel}>{title}</div>
      <FishCanvas colors={colors} editable={false} height={200} />
      {predatorPresent ? (
        <Readout label="행동 성향" value={bold.label} />
      ) : (
        <>
          <Readout label="주황 비중" value={`${stats.orangePct}%`} />
          <Readout label="검정 비중" value={`${stats.blackPct}%`} />
        </>
      )}
    </div>
  );
}

